validate_date() {
  local date=$1
  local year=${date:0:4}
  local month=${date:5:2}
  local day=${date:8:2}

  if [ $month -lt 1 ] || [ $month -gt 12 ]; then
    return 1
  fi

  if [ $day -lt 1 ] || [ $day -gt 31 ]; then
    return 1
  fi

  return 0
}

validate_date "2024-03-15"
